let initialState = {
  frends: [
    { name: "Tod", ava: "ava1" },
    { name: "Olya", ava: "ava2" },
    { name: "Vell", ava: "ava3" },
    { name: "Kolya", ava: "ava4" },
    { name: "Loh", ava: "ava5" }
  ]
};

const frendsDataReducer = (state = initialState, action) => {
  return state;
};

export default frendsDataReducer;
